-- Accounting locks, immutable close evidence and separately reversible annual nominal-account closing.
CREATE TABLE accounting.fiscal_year_controls(id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES core.companies(id),state text NOT NULL DEFAULT 'OPEN' CHECK(state IN('OPEN','CLOSED')),version bigint NOT NULL DEFAULT 1,current_closing_id uuid CHECK((state='CLOSED')=(current_closing_id IS NOT NULL)),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),FOREIGN KEY(company_id,id)REFERENCES accounting.fiscal_years(company_id,id));
CREATE TABLE accounting.period_close_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),period_id uuid NOT NULL,revision bigint NOT NULL CHECK(revision>0),report jsonb NOT NULL,financial_hash text NOT NULL CHECK(financial_hash~'^[0-9a-f]{64}$'),reference text NOT NULL CHECK(length(btrim(reference))BETWEEN 1 AND 200),reason text NOT NULL CHECK(length(btrim(reason))BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),UNIQUE(company_id,period_id,id),UNIQUE(company_id,period_id,revision),FOREIGN KEY(company_id,period_id)REFERENCES accounting.periods(company_id,id));
ALTER TABLE accounting.periods ADD COLUMN current_close_snapshot_id uuid;
ALTER TABLE accounting.periods ADD FOREIGN KEY(company_id,id,current_close_snapshot_id)REFERENCES accounting.period_close_snapshots(company_id,period_id,id);
CREATE TABLE accounting.period_close_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),period_id uuid NOT NULL,snapshot_id uuid,period_version bigint NOT NULL,action text NOT NULL CHECK(action IN('CLOSED','REOPENED')),reference text NOT NULL CHECK(length(btrim(reference))BETWEEN 1 AND 200),reason text NOT NULL CHECK(length(btrim(reason))BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),UNIQUE(company_id,action,reference),UNIQUE(company_id,period_id,period_version),FOREIGN KEY(company_id,period_id)REFERENCES accounting.periods(company_id,id),FOREIGN KEY(company_id,period_id,snapshot_id)REFERENCES accounting.period_close_snapshots(company_id,period_id,id));
CREATE TABLE accounting.year_end_closings(id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES core.companies(id),fiscal_year_id uuid NOT NULL,revision bigint NOT NULL CHECK(revision>0),reference text NOT NULL,reason text NOT NULL,retained_account_id uuid NOT NULL,profit numeric NOT NULL,journal_entry_id uuid,balances jsonb NOT NULL,report jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),UNIQUE(company_id,fiscal_year_id,id),UNIQUE(company_id,fiscal_year_id,revision),UNIQUE(company_id,reference),FOREIGN KEY(company_id,id)REFERENCES platform.documents(company_id,id),FOREIGN KEY(company_id,fiscal_year_id)REFERENCES accounting.fiscal_years(company_id,id),FOREIGN KEY(company_id,retained_account_id)REFERENCES accounting.accounts(company_id,id),FOREIGN KEY(company_id,journal_entry_id)REFERENCES accounting.journal_entries(company_id,id)DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE accounting.year_end_reversals(id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES core.companies(id),closing_id uuid NOT NULL,reference text NOT NULL,reason text NOT NULL,journal_entry_id uuid,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),UNIQUE(company_id,closing_id),UNIQUE(company_id,reference),FOREIGN KEY(company_id,id)REFERENCES platform.documents(company_id,id),FOREIGN KEY(company_id,closing_id)REFERENCES accounting.year_end_closings(company_id,id),FOREIGN KEY(company_id,journal_entry_id)REFERENCES accounting.journal_entries(company_id,id)DEFERRABLE INITIALLY DEFERRED);
ALTER TABLE accounting.fiscal_year_controls ADD FOREIGN KEY(company_id,id,current_closing_id)REFERENCES accounting.year_end_closings(company_id,fiscal_year_id,id)DEFERRABLE INITIALLY DEFERRED;
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['fiscal_year_controls','period_close_snapshots','period_close_events','year_end_closings','year_end_reversals']LOOP EXECUTE format('ALTER TABLE accounting.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE accounting.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY company_scope ON accounting.%I USING(company_id=core.current_company())WITH CHECK(company_id=core.current_company())',t);IF t<>'fiscal_year_controls'THEN EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON accounting.%I FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation()',t);END IF;END LOOP;END $$;
CREATE TRIGGER touch_version BEFORE UPDATE ON accounting.fiscal_year_controls FOR EACH ROW EXECUTE FUNCTION core.touch_version();
CREATE FUNCTION accounting.seed_year_control()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN INSERT INTO accounting.fiscal_year_controls(id,company_id)VALUES(NEW.id,NEW.company_id);RETURN NEW;END $$;
CREATE TRIGGER year_control AFTER INSERT ON accounting.fiscal_years FOR EACH ROW EXECUTE FUNCTION accounting.seed_year_control();
-- Existing years are seeded after all constraint triggers have been installed.
INSERT INTO identity.permissions(code,description)VALUES('accounting.periods.read','Read accounting close preflight and immutable evidence'),('accounting.periods.manage','Create fiscal calendars and configure retained earnings'),('accounting.periods.close','Close an accounting period after reconciliation'),('accounting.periods.reopen','Reopen accounting periods in reverse chronological order'),('accounting.years.close','Close annual nominal balances to retained earnings'),('accounting.years.reopen','Reverse annual closing before reopening periods');
CREATE FUNCTION identity.seed_period_close_roles(c uuid)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN
 INSERT INTO identity.role_permissions(company_id,role_id,permission_code)SELECT c,r.id,p.code FROM identity.roles r CROSS JOIN identity.permissions p WHERE r.company_id=c AND r.code IN('ADMIN','FINANCE')AND(p.code LIKE'accounting.periods.%'OR p.code LIKE'accounting.years.%')ON CONFLICT DO NOTHING;
 INSERT INTO accounting.accounts(company_id,code,name,kind)VALUES(c,'3100','Retained Earnings','EQUITY')ON CONFLICT(company_id,code)DO NOTHING;
 INSERT INTO accounting.account_mappings(company_id,purpose,account_id)SELECT c,'RETAINED_EARNINGS',id FROM accounting.accounts WHERE company_id=c AND code='3100'AND name='Retained Earnings'AND kind='EQUITY'AND control_kind IS NULL ON CONFLICT DO NOTHING;
 END $$;
-- Backfill runs last, checking deferred guards while each company context is active.
CREATE FUNCTION accounting.require_close_access(p_cap text)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 PERFORM accounting.bas_require_access('accounting.periods.read');PERFORM accounting.require_reconciliation_access();IF p_cap<>'accounting.periods.read'THEN PERFORM purchase.require_access(p_cap);END IF;END $$;
CREATE VIEW accounting.year_end_journal_ids WITH(security_invoker=true)AS SELECT company_id,journal_entry_id FROM accounting.year_end_closings WHERE journal_entry_id IS NOT NULL UNION ALL SELECT company_id,journal_entry_id FROM accounting.year_end_reversals WHERE journal_entry_id IS NOT NULL;
CREATE VIEW accounting.business_journal_entries WITH(security_invoker=true)AS SELECT j.* FROM accounting.journal_entries j WHERE NOT EXISTS(SELECT 1 FROM accounting.year_end_journal_ids y WHERE y.company_id=j.company_id AND y.journal_entry_id=j.id);
CREATE VIEW accounting.close_stock_movements WITH(security_invoker=true)AS
 SELECT o.company_id,b.id AS stock_balance_id,coalesce(d.business_date,(o.created_at AT TIME ZONE c.timezone)::date)AS effective_date,o.quantity AS quantity,0::numeric AS value FROM inventory.stock_openings o JOIN core.companies c ON c.id=o.company_id JOIN inventory.stock_balances b ON b.company_id=o.company_id AND b.warehouse_id=o.warehouse_id AND b.product_id=o.product_id LEFT JOIN inventory.valuation_openings v ON v.company_id=b.company_id AND v.stock_balance_id=b.id LEFT JOIN platform.documents d ON d.company_id=v.company_id AND d.id=v.id
 UNION ALL SELECT v.company_id,v.stock_balance_id,d.business_date,0,v.value FROM inventory.valuation_openings v JOIN platform.documents d ON d.company_id=v.company_id AND d.id=v.id
 UNION ALL SELECT l.company_id,l.stock_balance_id,d.business_date,l.base_quantity,l.valuation_amount FROM purchase.receipt_lines l JOIN platform.documents d ON d.company_id=l.company_id AND d.id=l.receipt_id WHERE l.stock_balance_id IS NOT NULL
 UNION ALL SELECT l.company_id,l.stock_balance_id,d.business_date,-l.quantity,-l.cost FROM inventory.stock_movements l JOIN inventory.pick_lines pl ON pl.company_id=l.company_id AND pl.id=l.pick_line_id JOIN platform.documents d ON d.company_id=pl.company_id AND d.id=pl.pick_id
 UNION ALL SELECT l.company_id,b.id,d.business_date,l.base_quantity,l.cost FROM inventory.sales_return_lines l JOIN inventory.sales_returns h ON h.company_id=l.company_id AND h.id=l.return_id JOIN sales.order_lines ol ON ol.company_id=l.company_id AND ol.id=l.order_line_id JOIN inventory.stock_balances b ON b.company_id=l.company_id AND b.warehouse_id=h.warehouse_id AND b.product_id=ol.product_id JOIN platform.documents d ON d.company_id=l.company_id AND d.id=l.return_id
 UNION ALL SELECT l.company_id,l.stock_balance_id,d.business_date,-l.base_quantity,-l.cost FROM purchase.return_lines l JOIN platform.documents d ON d.company_id=l.company_id AND d.id=l.return_id WHERE l.stock_balance_id IS NOT NULL
 UNION ALL SELECT l.company_id,l.stock_balance_id,d.business_date,l.quantity_delta,l.value_delta FROM inventory.operation_lines l JOIN platform.documents d ON d.company_id=l.company_id AND d.id=l.operation_id
 UNION ALL SELECT l.company_id,l.stock_balance_id,d.business_date,-l.quantity,-l.cost FROM inventory.transit_transfer_lines l JOIN platform.documents d ON d.company_id=l.company_id AND d.id=l.transfer_id
 UNION ALL SELECT l.company_id,l.stock_balance_id,d.business_date,l.quantity,l.cost FROM inventory.transit_event_lines l JOIN platform.documents d ON d.company_id=l.company_id AND d.id=l.event_id WHERE l.stock_balance_id IS NOT NULL
 UNION ALL SELECT l.company_id,l.stock_balance_id,d.business_date,0,l.inventory_delta FROM inventory.purchase_value_adjustments l JOIN platform.documents d ON d.company_id=l.company_id AND d.id=l.document_id WHERE l.stock_balance_id IS NOT NULL;
CREATE FUNCTION accounting.close_financials(p_from date,p_to date)RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog SET jit=off AS $$
 WITH gl AS MATERIALIZED(SELECT l.account_id,l.party_id,a.kind,a.control_kind,coalesce(sum(l.debit-l.credit),0)AS balance,coalesce(sum(l.debit-l.credit)FILTER(WHERE j.posting_date<p_from),0)AS opening,coalesce(sum(l.debit)FILTER(WHERE j.posting_date>=p_from),0)AS debits,coalesce(sum(l.credit)FILTER(WHERE j.posting_date>=p_from),0)AS credits FROM accounting.journal_lines l JOIN accounting.business_journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id JOIN accounting.accounts a ON a.company_id=l.company_id AND a.id=l.account_id WHERE l.company_id=core.current_company()AND j.posting_date<p_to GROUP BY l.account_id,l.party_id,a.kind,a.control_kind HAVING sum(l.debit-l.credit)<>0 OR coalesce(sum(l.debit+l.credit)FILTER(WHERE j.posting_date>=p_from),0)<>0),
 stock AS MATERIALIZED(SELECT m.stock_balance_id,b.warehouse_id,b.product_id,sum(m.quantity)AS quantity,sum(m.value)AS value,coalesce(sum(m.quantity)FILTER(WHERE m.effective_date<p_from),0)AS opening_quantity,coalesce(sum(m.value)FILTER(WHERE m.effective_date<p_from),0)AS opening_value,coalesce(sum(greatest(m.quantity,0))FILTER(WHERE m.effective_date>=p_from),0)AS quantity_in,coalesce(sum(greatest(-m.quantity,0))FILTER(WHERE m.effective_date>=p_from),0)AS quantity_out,coalesce(sum(greatest(m.value,0))FILTER(WHERE m.effective_date>=p_from),0)AS value_in,coalesce(sum(greatest(-m.value,0))FILTER(WHERE m.effective_date>=p_from),0)AS value_out FROM accounting.close_stock_movements m JOIN inventory.stock_balances b ON b.company_id=m.company_id AND b.id=m.stock_balance_id WHERE m.company_id=core.current_company()AND m.effective_date<p_to GROUP BY m.stock_balance_id,b.warehouse_id,b.product_id HAVING sum(m.quantity)<>0 OR sum(m.value)<>0 OR coalesce(sum(abs(m.quantity)+abs(m.value))FILTER(WHERE m.effective_date>=p_from),0)<>0),
 transit AS MATERIALIZED(SELECT l.id,t.transit_account_id,l.quantity-coalesce((SELECT sum(x.quantity)FROM inventory.transit_event_lines x JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.event_id WHERE x.company_id=l.company_id AND x.transfer_line_id=l.id AND d.business_date<p_to),0)AS quantity,l.cost-coalesce((SELECT sum(x.cost)FROM inventory.transit_event_lines x JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.event_id WHERE x.company_id=l.company_id AND x.transfer_line_id=l.id AND d.business_date<p_to),0)AS value FROM inventory.transit_transfer_lines l JOIN inventory.transit_transfers t ON t.company_id=l.company_id AND t.id=l.transfer_id JOIN platform.documents d ON d.company_id=l.company_id AND d.id=l.transfer_id WHERE l.company_id=core.current_company()AND d.business_date<p_to),
 items AS MATERIALIZED(SELECT m.side,m.item_line_id,CASE WHEN m.side='AR'THEN i.party_id ELSE b.party_id END AS party_id,sum(m.amount)AS balance FROM accounting.report_open_item_movements m JOIN accounting.report_control_dates d ON d.company_id=m.company_id AND d.source_document_id=m.source_document_id AND d.side=m.side LEFT JOIN sales.invoice_lines il ON m.side='AR'AND il.company_id=m.company_id AND il.id=m.item_line_id LEFT JOIN sales.invoices i ON i.company_id=il.company_id AND i.id=il.invoice_id LEFT JOIN purchase.bill_lines bl ON m.side='AP'AND bl.company_id=m.company_id AND bl.id=m.item_line_id LEFT JOIN purchase.bills b ON b.company_id=bl.company_id AND b.id=bl.bill_id WHERE m.company_id=core.current_company()AND d.posting_date<p_to GROUP BY m.side,m.item_line_id,i.party_id,b.party_id HAVING sum(m.amount)<>0),
 controls AS(SELECT coalesce((SELECT sum(value)FROM stock),0)+coalesce((SELECT sum(value)FROM transit),0)-coalesce((SELECT sum(balance)FROM gl WHERE control_kind='INVENTORY'),0)AS inventory_difference,
 (SELECT count(*)FROM(SELECT coalesce(i.side,g.side)AS side,coalesce(i.party_id,g.party_id)AS party,coalesce(i.amount,0)-coalesce(g.amount,0)AS diff FROM(SELECT side,party_id,sum(balance)AS amount FROM items GROUP BY side,party_id)i FULL JOIN(SELECT CASE control_kind WHEN'AR'THEN'AR'ELSE'AP'END AS side,party_id,sum(CASE WHEN control_kind='AR'THEN balance ELSE -balance END)AS amount FROM gl WHERE control_kind IN('AR','AP')GROUP BY control_kind,party_id)g ON g.side=i.side AND g.party_id IS NOT DISTINCT FROM i.party_id)x WHERE diff<>0)AS settlement_errors)
 SELECT jsonb_build_object('from',p_from,'to',p_to,'gl',coalesce((SELECT jsonb_agg(jsonb_build_object('accountId',account_id,'partyId',party_id,'kind',kind,'controlKind',control_kind,'balance',balance::text,'opening',opening::text,'periodDebit',debits::text,'periodCredit',credits::text)ORDER BY account_id,party_id)FROM gl),'[]'::jsonb),'inventory',coalesce((SELECT jsonb_agg(jsonb_build_object('stockBalanceId',stock_balance_id,'warehouseId',warehouse_id,'productId',product_id,'quantity',quantity::text,'value',value::text,'openingQuantity',opening_quantity::text,'openingValue',opening_value::text,'quantityIn',quantity_in::text,'quantityOut',quantity_out::text,'valueIn',value_in::text,'valueOut',value_out::text)ORDER BY stock_balance_id)FROM stock),'[]'::jsonb),'transit',coalesce((SELECT jsonb_agg(jsonb_build_object('lineId',id,'accountId',transit_account_id,'quantity',quantity::text,'value',value::text)ORDER BY id)FROM transit WHERE quantity<>0 OR value<>0),'[]'::jsonb),'openItems',coalesce((SELECT jsonb_agg(jsonb_build_object('side',side,'lineId',item_line_id,'partyId',party_id,'balance',balance::text)ORDER BY side,item_line_id)FROM items),'[]'::jsonb),'gst',accounting.bas_summary(p_from,p_to)->'financial','inventoryDifference',inventory_difference::text,'settlementErrorCount',settlement_errors,'trialBalanceDifference',coalesce((SELECT sum(balance)FROM gl),0)::text)FROM controls
 $$;
CREATE FUNCTION accounting.close_hash(p_financial jsonb)RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT encode(sha256(convert_to(accounting.bas_canonical_json(p_financial)::text,'UTF8')),'hex')$$;

CREATE FUNCTION accounting.year_closing_bridge(p_to date)RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$SELECT coalesce(jsonb_agg(jsonb_build_object('accountId',account_id,'debit',debits::text,'credit',credits::text,'signed',balance::text)ORDER BY account_id),'[]'::jsonb)FROM(SELECT l.account_id,sum(l.debit)AS debits,sum(l.credit)AS credits,sum(l.debit-l.credit)AS balance FROM accounting.journal_lines l JOIN accounting.journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id JOIN accounting.year_end_journal_ids y ON y.company_id=j.company_id AND y.journal_entry_id=j.id WHERE l.company_id=core.current_company()AND j.posting_date<p_to GROUP BY l.account_id HAVING sum(l.debit-l.credit)<>0)x$$;
CREATE FUNCTION accounting.period_preflight(p_id uuid,p_bas_na boolean DEFAULT false)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog SET jit=off AS $$
 DECLARE c uuid:=core.current_company();p accounting.periods;y accounting.fiscal_years;f jsonb;issues jsonb:='[]';live jsonb;bas jsonb;covered int;required boolean;activity boolean;bad int;today date;BEGIN
 PERFORM accounting.require_close_access('accounting.periods.read');SELECT*INTO p FROM accounting.periods WHERE company_id=c AND id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'Accounting period unavailable' USING ERRCODE='HT404';END IF;SELECT*INTO y FROM accounting.fiscal_years WHERE company_id=c AND id=p.fiscal_year_id;
 SELECT (now()AT TIME ZONE timezone)::date,gst_registered INTO today,required FROM core.companies WHERE id=c;
 IF p.ends_on>today THEN issues:=issues||jsonb_build_array('PERIOD_NOT_ENDED');END IF;
 IF p.starts_on<y.starts_on OR p.ends_on>y.ends_on OR EXISTS(SELECT 1 FROM accounting.periods q WHERE q.company_id=c AND q.id<>p.id AND q.starts_on<p.ends_on AND q.ends_on>p.starts_on)THEN issues:=issues||jsonb_build_array('INVALID_ACCOUNTING_CALENDAR');END IF;
 IF EXISTS(SELECT 1 FROM accounting.periods WHERE company_id=c AND starts_on<p.starts_on AND state<>'CLOSED')THEN issues:=issues||jsonb_build_array('EARLIER_PERIODS_OPEN');END IF;
 IF EXISTS(SELECT 1 FROM accounting.fiscal_year_controls WHERE company_id=c AND id=p.fiscal_year_id AND state='CLOSED')THEN issues:=issues||jsonb_build_array('FISCAL_YEAR_CLOSED');END IF;
 f:=accounting.close_financials(p.starts_on,p.ends_on);
 SELECT coalesce(jsonb_agg(jsonb_build_object('code',check_code,'entityId',entity_id,'expected',expected::text,'actual',actual::text,'unit',unit)ORDER BY check_code,entity_id),'[]'::jsonb)INTO live FROM accounting.reconciliation_checks()WHERE expected IS DISTINCT FROM actual;
 IF jsonb_array_length(live)>0 THEN issues:=issues||jsonb_build_array('CURRENT_SUBLEDGER_INCONSISTENT');END IF;
 IF(f->>'inventoryDifference')::numeric<>0 OR(f->>'settlementErrorCount')::int>0 OR(f->>'trialBalanceDifference')::numeric<>0 OR(f->'gst'->>'glErrorCount')::int+(f->'gst'->>'roleErrorCount')::int+(f->'gst'->>'missingAccountCount')::int>0 OR(f->'gst'->>'labelDifference')::numeric<>0 THEN issues:=issues||jsonb_build_array('HISTORICAL_LEDGERS_UNRECONCILED');END IF;
 SELECT coalesce(sum(least(b.to_date,p.ends_on)-greatest(b.from_date,p.starts_on)),0),coalesce(jsonb_agg(jsonb_build_object('id',b.id,'from',b.from_date,'to',b.to_date,'state',k.state,'reportingMethod',b.reporting_method,'calculationMethod',b.calculation_method,'snapshotId',k.current_snapshot_id)ORDER BY b.from_date),'[]'::jsonb),count(*)FILTER(WHERE b.to_date<=p.ends_on AND k.state='OPEN')INTO covered,bas,bad FROM accounting.bas_effective_periods b JOIN accounting.bas_period_controls k ON k.company_id=b.company_id AND k.id=b.id WHERE b.company_id=c AND b.from_date<p.ends_on AND b.to_date>p.starts_on;
 SELECT EXISTS(SELECT 1 FROM accounting.bas_tax_events WHERE company_id=c AND attribution_date>=p.starts_on AND attribution_date<p.ends_on AND gst_amount<>0)OR EXISTS(SELECT 1 FROM accounting.bas_turnover(p.starts_on,p.ends_on)WHERE gross_amount<>0)OR EXISTS(SELECT 1 FROM purchase.bill_lines l JOIN purchase.bills b ON b.company_id=l.company_id AND b.id=l.bill_id JOIN platform.documents d ON d.company_id=b.company_id AND d.id=b.id WHERE l.company_id=c AND((b.invoice_date>=p.starts_on AND b.invoice_date<p.ends_on)OR(d.business_date>=p.starts_on AND d.business_date<p.ends_on))AND(l.snapshot->>'gstRegistered')::boolean) INTO activity;
 required:=required OR activity OR covered>0;
 IF p_bas_na THEN IF activity OR covered>0 THEN issues:=issues||jsonb_build_array('BAS_NOT_APPLICABLE_CONTRADICTS_SOURCES');END IF;ELSE IF required AND covered<>p.ends_on-p.starts_on THEN issues:=issues||jsonb_build_array('BAS_COVERAGE_MISSING');END IF;END IF;
 IF bad>0 THEN issues:=issues||jsonb_build_array('ENDED_BAS_PERIOD_NOT_FINALIZED');END IF;
 IF EXISTS(SELECT 1 FROM accounting.bas_effective_periods b JOIN accounting.bas_period_controls k ON k.company_id=b.company_id AND k.id=b.id JOIN accounting.bas_snapshots bs ON bs.company_id=k.company_id AND bs.id=k.current_snapshot_id WHERE b.company_id=c AND b.from_date<p.ends_on AND b.to_date>p.starts_on AND k.state IN('FINALIZED','LODGED')AND accounting.bas_financial_hash(accounting.bas_report(b.from_date,b.to_date,b.reporting_method,b.calculation_method))<>bs.financial_hash)THEN issues:=issues||jsonb_build_array('BAS_SNAPSHOT_DRIFT');END IF;
 RETURN jsonb_build_object('companyId',c,'periodId',p.id,'fiscalYearId',p.fiscal_year_id,'from',p.starts_on,'to',p.ends_on,'state',p.state,'version',p.version,'legacyUncertified',p.state='CLOSED'AND p.current_close_snapshot_id IS NULL,'basNotApplicableConfirmed',p_bas_na,'basRequired',required,'basPeriods',bas,'status',CASE WHEN jsonb_array_length(issues)=0 THEN'READY'ELSE'BLOCKED'END,'issues',issues,'currentMismatches',live,'financial',f,'yearEndBridge',accounting.year_closing_bridge(p.ends_on),'snapshotAt',statement_timestamp());END $$;
CREATE FUNCTION accounting.close_period(p_id uuid,p_version bigint,p_reference text,p_reason text,p_bas_na boolean)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
 DECLARE c uuid:=core.current_company();p accounting.periods;r jsonb;sid uuid:=gen_random_uuid();rev bigint;BEGIN
 PERFORM accounting.require_close_access('accounting.periods.close');PERFORM accounting.bas_lock(c,true);SELECT*INTO p FROM accounting.periods WHERE company_id=c AND id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Accounting period unavailable' USING ERRCODE='HT404';END IF;
 IF p.version IS DISTINCT FROM p_version OR(p.state='CLOSED'AND p.current_close_snapshot_id IS NOT NULL)THEN RAISE EXCEPTION 'Period already closed or version changed' USING ERRCODE='HR409';END IF;
 IF p_reference IS NULL OR length(btrim(p_reference))NOT BETWEEN 1 AND 200 OR p_reason IS NULL OR length(btrim(p_reason))NOT BETWEEN 1 AND 2000 OR p_bas_na IS NULL THEN RAISE EXCEPTION 'Reference, reason and BAS confirmation required' USING ERRCODE='HR422';END IF;
 r:=accounting.period_preflight(p_id,p_bas_na);IF r->>'status'<>'READY'THEN RAISE EXCEPTION 'Period close preflight failed: %',r->'issues' USING ERRCODE='HR409';END IF;
 SELECT coalesce(max(revision),0)+1 INTO rev FROM accounting.period_close_snapshots WHERE company_id=c AND period_id=p_id;
 INSERT INTO accounting.period_close_snapshots(id,company_id,period_id,revision,report,financial_hash,reference,reason,created_by)VALUES(sid,c,p_id,rev,r,accounting.close_hash(r->'financial'),btrim(p_reference),btrim(p_reason),core.current_actor());
 INSERT INTO accounting.period_close_events(company_id,period_id,snapshot_id,period_version,action,reference,reason,created_by)VALUES(c,p_id,sid,p.version+1,'CLOSED',btrim(p_reference),btrim(p_reason),core.current_actor());
 UPDATE accounting.periods SET state='CLOSED',current_close_snapshot_id=sid WHERE company_id=c AND id=p_id;RETURN sid;END $$;
CREATE FUNCTION accounting.reopen_period(p_id uuid,p_version bigint,p_reference text,p_reason text)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
 DECLARE c uuid:=core.current_company();p accounting.periods;event_id uuid;BEGIN
 PERFORM accounting.require_close_access('accounting.periods.reopen');PERFORM accounting.bas_lock(c,true);SELECT*INTO p FROM accounting.periods WHERE company_id=c AND id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Accounting period unavailable' USING ERRCODE='HT404';END IF;
 IF p.version IS DISTINCT FROM p_version OR p.state<>'CLOSED'THEN RAISE EXCEPTION 'Closed period and current version required' USING ERRCODE='HR409';END IF;
 IF p_reference IS NULL OR length(btrim(p_reference))NOT BETWEEN 1 AND 200 OR p_reason IS NULL OR length(btrim(p_reason))NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Reference and reason required' USING ERRCODE='HR422';END IF;
 IF EXISTS(SELECT 1 FROM accounting.fiscal_year_controls WHERE company_id=c AND id=p.fiscal_year_id AND state='CLOSED')THEN RAISE EXCEPTION 'Reopen the fiscal year and reverse its closing first' USING ERRCODE='HR409';END IF;
 IF EXISTS(SELECT 1 FROM accounting.periods WHERE company_id=c AND state='CLOSED'AND ends_on>p.ends_on)THEN RAISE EXCEPTION 'Reopen later periods first' USING ERRCODE='HR409';END IF;
 INSERT INTO accounting.period_close_events(company_id,period_id,snapshot_id,period_version,action,reference,reason,created_by)VALUES(c,p_id,p.current_close_snapshot_id,p.version+1,'REOPENED',btrim(p_reference),btrim(p_reason),core.current_actor())RETURNING id INTO event_id;
 UPDATE accounting.periods SET state='OPEN'WHERE company_id=c AND id=p_id;RETURN event_id;END $$;
CREATE FUNCTION accounting.guard_period_state()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN
 IF OLD.current_close_snapshot_id IS NOT NULL AND ROW(NEW.company_id,NEW.fiscal_year_id,NEW.starts_on,NEW.ends_on)IS DISTINCT FROM ROW(OLD.company_id,OLD.fiscal_year_id,OLD.starts_on,OLD.ends_on)THEN RAISE EXCEPTION 'Managed period calendar is immutable' USING ERRCODE='HR409';END IF;
 IF(OLD.current_close_snapshot_id IS NOT NULL OR NEW.current_close_snapshot_id IS NOT NULL)AND ROW(NEW.state,NEW.current_close_snapshot_id)IS DISTINCT FROM ROW(OLD.state,OLD.current_close_snapshot_id)AND NOT EXISTS(SELECT 1 FROM accounting.period_close_events WHERE company_id=NEW.company_id AND period_id=NEW.id AND period_version=NEW.version AND action=CASE NEW.state WHEN'OPEN'THEN'REOPENED'ELSE'CLOSED'END AND snapshot_id IS NOT DISTINCT FROM NEW.current_close_snapshot_id)THEN RAISE EXCEPTION 'Use controlled period close/reopen operations' USING ERRCODE='HR409';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER managed_period AFTER UPDATE ON accounting.periods DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION accounting.guard_period_state();
CREATE FUNCTION accounting.lock_calendar()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM accounting.bas_lock(coalesce(NEW.company_id,OLD.company_id),true);RETURN coalesce(NEW,OLD);END $$;
CREATE TRIGGER close_calendar_lock BEFORE INSERT OR UPDATE OR DELETE ON accounting.periods FOR EACH ROW EXECUTE FUNCTION accounting.lock_calendar();
CREATE TRIGGER close_calendar_lock BEFORE INSERT OR UPDATE OR DELETE ON accounting.fiscal_years FOR EACH ROW EXECUTE FUNCTION accounting.lock_calendar();
CREATE FUNCTION accounting.create_fiscal_year(p_label text,p_start date,p_end date)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE c uuid:=core.current_company();y uuid:=gen_random_uuid();m int;BEGIN
 PERFORM accounting.require_close_access('accounting.periods.manage');PERFORM accounting.bas_lock(c,true);SELECT financial_year_start_month INTO m FROM core.companies WHERE id=c;
 IF p_label IS NULL OR length(btrim(p_label))NOT BETWEEN 1 AND 200 OR p_start IS NULL OR p_start<'0002-01-01'OR p_end IS NULL OR p_end<>(p_start+interval'1 year')::date OR extract(day FROM p_start)<>1 OR extract(month FROM p_start)<>m THEN RAISE EXCEPTION 'Use one full configured fiscal year with a label' USING ERRCODE='HR422';END IF;
 IF EXISTS(SELECT 1 FROM accounting.fiscal_years WHERE company_id=c AND starts_on<p_end AND ends_on>p_start)OR EXISTS(SELECT 1 FROM accounting.periods WHERE company_id=c AND starts_on<p_end AND ends_on>p_start)THEN RAISE EXCEPTION 'Fiscal calendar overlaps existing periods' USING ERRCODE='HR409';END IF;
 INSERT INTO accounting.fiscal_years(id,company_id,label,starts_on,ends_on,created_by)VALUES(y,c,btrim(p_label),p_start,p_end,core.current_actor());
 INSERT INTO accounting.periods(company_id,fiscal_year_id,starts_on,ends_on,created_by)SELECT c,y,d::date,(d+interval'1 month')::date,core.current_actor()FROM generate_series(p_start,p_end-interval'1 month',interval'1 month')d;RETURN y;END $$;

ALTER TABLE accounting.fiscal_year_controls ADD CONSTRAINT year_state_pointer CHECK((state='CLOSED')=(current_closing_id IS NOT NULL));
CREATE FUNCTION accounting.year_close_plan(p_year uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog SET jit=off AS $$
 DECLARE c uuid:=core.current_company();y accounting.fiscal_years;k accounting.fiscal_year_controls;issues jsonb:='[]';balances jsonb;profit numeric;lastp uuid;lastreport jsonb;retain uuid;days int;today date;BEGIN
 PERFORM accounting.require_close_access('accounting.periods.read');SELECT*INTO y FROM accounting.fiscal_years WHERE company_id=c AND id=p_year;IF NOT FOUND THEN RAISE EXCEPTION 'Fiscal year unavailable' USING ERRCODE='HT404';END IF;SELECT*INTO k FROM accounting.fiscal_year_controls WHERE company_id=c AND id=p_year;SELECT(now()AT TIME ZONE timezone)::date INTO today FROM core.companies WHERE id=c;
 IF y.ends_on>today THEN issues:=issues||jsonb_build_array('FISCAL_YEAR_NOT_ENDED');END IF;
 IF k.state<>'OPEN'THEN issues:=issues||jsonb_build_array('FISCAL_YEAR_ALREADY_CLOSED');END IF;
 IF EXISTS(SELECT 1 FROM accounting.fiscal_years f JOIN accounting.fiscal_year_controls q ON q.company_id=f.company_id AND q.id=f.id WHERE f.company_id=c AND f.ends_on<=y.starts_on AND q.state<>'CLOSED')THEN issues:=issues||jsonb_build_array('EARLIER_YEARS_NOT_CLOSED');END IF;
 SELECT coalesce(sum(ends_on-starts_on),0)INTO days FROM accounting.periods WHERE company_id=c AND fiscal_year_id=y.id;
 IF days<>y.ends_on-y.starts_on OR NOT EXISTS(SELECT 1 FROM accounting.periods WHERE company_id=c AND fiscal_year_id=y.id AND starts_on=y.starts_on)OR NOT EXISTS(SELECT 1 FROM accounting.periods WHERE company_id=c AND fiscal_year_id=y.id AND ends_on=y.ends_on)OR EXISTS(SELECT 1 FROM accounting.periods a JOIN accounting.periods b ON b.company_id=a.company_id AND b.id<>a.id AND b.starts_on<a.ends_on AND b.ends_on>a.starts_on WHERE a.company_id=c AND a.fiscal_year_id=y.id)OR EXISTS(SELECT 1 FROM accounting.periods WHERE company_id=c AND fiscal_year_id=y.id AND(starts_on<y.starts_on OR ends_on>y.ends_on))THEN issues:=issues||jsonb_build_array('INVALID_FISCAL_CALENDAR');END IF;
 IF EXISTS(SELECT 1 FROM accounting.periods WHERE company_id=c AND fiscal_year_id=y.id AND(state<>'CLOSED'OR current_close_snapshot_id IS NULL))THEN issues:=issues||jsonb_build_array('PERIOD_CLOSE_EVIDENCE_REQUIRED');END IF;
 IF EXISTS(SELECT 1 FROM accounting.periods p JOIN accounting.period_close_snapshots s ON s.company_id=p.company_id AND s.id=p.current_close_snapshot_id WHERE p.company_id=c AND p.fiscal_year_id=y.id AND p.state='CLOSED'AND accounting.close_hash(accounting.close_financials(p.starts_on,p.ends_on))<>s.financial_hash)THEN issues:=issues||jsonb_build_array('CLOSED_PERIOD_SNAPSHOT_DRIFT');END IF;
 IF EXISTS(SELECT l.account_id FROM accounting.journal_lines l JOIN accounting.journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id JOIN accounting.accounts a ON a.company_id=l.company_id AND a.id=l.account_id WHERE l.company_id=c AND a.kind IN('REVENUE','EXPENSE')AND j.posting_date<y.starts_on GROUP BY l.account_id HAVING sum(l.debit-l.credit)<>0)THEN issues:=issues||jsonb_build_array('PRIOR_NOMINAL_BALANCES_NOT_CLOSED');END IF;
 SELECT a.id INTO retain FROM accounting.account_mappings m JOIN accounting.accounts a ON a.company_id=m.company_id AND a.id=m.account_id WHERE m.company_id=c AND m.purpose='RETAINED_EARNINGS'AND a.active AND a.kind='EQUITY'AND a.control_kind IS NULL;
 IF retain IS NULL THEN issues:=issues||jsonb_build_array('RETAINED_EARNINGS_ACCOUNT_REQUIRED');END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('accountId',id,'kind',kind,'balance',balance::text)ORDER BY id),'[]'::jsonb),coalesce(-sum(balance),0)INTO balances,profit FROM(SELECT a.id,a.kind,sum(l.debit-l.credit)AS balance FROM accounting.journal_lines l JOIN accounting.business_journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id JOIN accounting.accounts a ON a.company_id=l.company_id AND a.id=l.account_id WHERE l.company_id=c AND a.kind IN('REVENUE','EXPENSE')AND j.posting_date>=y.starts_on AND j.posting_date<y.ends_on GROUP BY a.id,a.kind HAVING sum(l.debit-l.credit)<>0)x;
 IF abs(profit)>999999999999999999.99 OR EXISTS(SELECT 1 FROM jsonb_array_elements(balances)x WHERE abs((x->>'balance')::numeric)>999999999999999999.99)THEN issues:=issues||jsonb_build_array('CLOSING_AMOUNT_OUT_OF_RANGE');END IF;
 SELECT id INTO lastp FROM accounting.periods WHERE company_id=c AND fiscal_year_id=y.id ORDER BY ends_on DESC LIMIT 1;
 IF lastp IS NOT NULL THEN lastreport:=accounting.period_preflight(lastp,coalesce((SELECT(report->>'basNotApplicableConfirmed')::boolean FROM accounting.period_close_snapshots WHERE company_id=c AND id=(SELECT current_close_snapshot_id FROM accounting.periods WHERE company_id=c AND id=lastp)),false));IF lastreport->>'status'<>'READY'THEN issues:=issues||jsonb_build_array('FINAL_PERIOD_PREFLIGHT_FAILED');END IF;END IF;
 RETURN jsonb_build_object('companyId',c,'fiscalYearId',y.id,'from',y.starts_on,'to',y.ends_on,'state',k.state,'version',k.version,'retainedAccountId',retain,'profit',profit::text,'balances',balances,'status',CASE WHEN jsonb_array_length(issues)=0 THEN'READY'ELSE'BLOCKED'END,'issues',issues,'lastPeriodPreflight',lastreport,'financial',accounting.close_financials(y.starts_on,y.ends_on),'snapshotAt',statement_timestamp());END $$;
CREATE FUNCTION accounting.write_year_journal(p_doc uuid,p_journal uuid,p_date date,p_kind text,p_lines jsonb)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE c uuid:=core.current_company();b uuid:=gen_random_uuid();BEGIN
 IF jsonb_array_length(p_lines)<2 THEN RAISE EXCEPTION 'Closing journal requires at least two lines' USING ERRCODE='HR422';END IF;
 INSERT INTO accounting.posting_batches(id,company_id,source_document_id,source_version,posting_kind,created_by)VALUES(b,c,p_doc,1,p_kind,core.current_actor());
 INSERT INTO accounting.journal_entries(id,company_id,posting_batch_id,posting_date,description,created_by)VALUES(p_journal,c,b,p_date,p_kind,core.current_actor());
 INSERT INTO accounting.journal_lines(company_id,journal_entry_id,account_id,debit,credit,created_by)SELECT c,p_journal,(x->>'accountId')::uuid,(x->>'debit')::numeric,(x->>'credit')::numeric,core.current_actor()FROM jsonb_array_elements(p_lines)x;
 END $$;
CREATE FUNCTION accounting.close_fiscal_year(p_year uuid,p_version bigint,p_reference text,p_reason text)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
 DECLARE c uuid:=core.current_company();y accounting.fiscal_years;k accounting.fiscal_year_controls;r jsonb;v uuid:=gen_random_uuid();j uuid;lines jsonb;profit numeric;rev bigint;BEGIN
 PERFORM accounting.require_close_access('accounting.years.close');PERFORM accounting.bas_lock(c,true);SELECT*INTO y FROM accounting.fiscal_years WHERE company_id=c AND id=p_year;IF NOT FOUND THEN RAISE EXCEPTION 'Fiscal year unavailable' USING ERRCODE='HT404';END IF;SELECT*INTO k FROM accounting.fiscal_year_controls WHERE company_id=c AND id=p_year FOR UPDATE;
 IF k.version IS DISTINCT FROM p_version OR k.state<>'OPEN'THEN RAISE EXCEPTION 'Open fiscal year and current version required' USING ERRCODE='HR409';END IF;
 IF p_reference IS NULL OR length(btrim(p_reference))NOT BETWEEN 1 AND 200 OR p_reason IS NULL OR length(btrim(p_reason))NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Reference and reason required' USING ERRCODE='HR422';END IF;
 r:=accounting.year_close_plan(p_year);IF r->>'status'<>'READY'THEN RAISE EXCEPTION 'Year close preflight failed: %',r->'issues' USING ERRCODE='HR409';END IF;profit:=(r->>'profit')::numeric;
 SELECT coalesce(jsonb_agg(jsonb_build_object('accountId',x->>'accountId','debit',greatest(-(x->>'balance')::numeric,0),'credit',greatest((x->>'balance')::numeric,0))),'[]'::jsonb)INTO lines FROM jsonb_array_elements(r->'balances')x;
 IF profit<>0 THEN lines:=lines||jsonb_build_array(jsonb_build_object('accountId',r->>'retainedAccountId','debit',greatest(-profit,0),'credit',greatest(profit,0)));END IF;
 IF jsonb_array_length(lines)>0 THEN j:=gen_random_uuid();END IF;
 SELECT coalesce(max(revision),0)+1 INTO rev FROM accounting.year_end_closings WHERE company_id=c AND fiscal_year_id=p_year;
 INSERT INTO platform.documents(id,company_id,document_type,number,business_date,state,created_by)VALUES(v,c,'YEAR_END_CLOSING','YEC-'||v::text,y.ends_on-1,'POSTED',core.current_actor());
 INSERT INTO accounting.year_end_closings(id,company_id,fiscal_year_id,revision,reference,reason,retained_account_id,profit,journal_entry_id,balances,report,created_by)VALUES(v,c,p_year,rev,btrim(p_reference),btrim(p_reason),(r->>'retainedAccountId')::uuid,profit,j,r->'balances',r,core.current_actor());
 IF j IS NOT NULL THEN PERFORM accounting.write_year_journal(v,j,y.ends_on-1,'YEAR_END_CLOSING',lines);END IF;
 UPDATE accounting.fiscal_year_controls SET state='CLOSED',current_closing_id=v WHERE company_id=c AND id=p_year;RETURN v;END $$;
CREATE FUNCTION accounting.reopen_fiscal_year(p_year uuid,p_version bigint,p_reference text,p_reason text)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
 DECLARE c uuid:=core.current_company();y accounting.fiscal_years;k accounting.fiscal_year_controls;cl accounting.year_end_closings;v uuid:=gen_random_uuid();j uuid;lines jsonb;BEGIN
 PERFORM accounting.require_close_access('accounting.years.reopen');PERFORM accounting.bas_lock(c,true);SELECT*INTO y FROM accounting.fiscal_years WHERE company_id=c AND id=p_year;IF NOT FOUND THEN RAISE EXCEPTION 'Fiscal year unavailable' USING ERRCODE='HT404';END IF;SELECT*INTO k FROM accounting.fiscal_year_controls WHERE company_id=c AND id=p_year FOR UPDATE;
 IF k.version IS DISTINCT FROM p_version OR k.state<>'CLOSED'THEN RAISE EXCEPTION 'Closed fiscal year and current version required' USING ERRCODE='HR409';END IF;
 IF p_reference IS NULL OR length(btrim(p_reference))NOT BETWEEN 1 AND 200 OR p_reason IS NULL OR length(btrim(p_reason))NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Reference and reason required' USING ERRCODE='HR422';END IF;
 IF EXISTS(SELECT 1 FROM accounting.periods WHERE company_id=c AND state='CLOSED'AND starts_on>=y.ends_on)OR EXISTS(SELECT 1 FROM accounting.fiscal_years f JOIN accounting.fiscal_year_controls q ON q.company_id=f.company_id AND q.id=f.id WHERE f.company_id=c AND f.starts_on>=y.ends_on AND q.state='CLOSED')THEN RAISE EXCEPTION 'Reopen later accounting periods and fiscal years first' USING ERRCODE='HR409';END IF;
 SELECT*INTO cl FROM accounting.year_end_closings WHERE company_id=c AND id=k.current_closing_id;
 IF cl.journal_entry_id IS NOT NULL THEN j:=gen_random_uuid();SELECT jsonb_agg(jsonb_build_object('accountId',account_id,'debit',credit,'credit',debit)ORDER BY account_id,id)INTO lines FROM accounting.journal_lines WHERE company_id=c AND journal_entry_id=cl.journal_entry_id;END IF;
 INSERT INTO platform.documents(id,company_id,document_type,number,business_date,state,created_by)VALUES(v,c,'YEAR_END_REVERSAL','YER-'||v::text,y.ends_on-1,'POSTED',core.current_actor());
 INSERT INTO accounting.year_end_reversals(id,company_id,closing_id,reference,reason,journal_entry_id,created_by)VALUES(v,c,cl.id,btrim(p_reference),btrim(p_reason),j,core.current_actor());
 IF j IS NOT NULL THEN PERFORM accounting.write_year_journal(v,j,y.ends_on-1,'YEAR_END_REVERSAL',lines);END IF;
 UPDATE accounting.fiscal_year_controls SET state='OPEN',current_closing_id=NULL WHERE company_id=c AND id=p_year;RETURN v;END $$;
CREATE FUNCTION accounting.configure_retained(p_account uuid,p_version bigint)RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE c uuid:=core.current_company();m accounting.account_mappings;v bigint;BEGIN
 PERFORM accounting.require_close_access('accounting.periods.manage');PERFORM accounting.bas_lock(c,true);IF NOT EXISTS(SELECT 1 FROM accounting.accounts WHERE company_id=c AND id=p_account AND active AND kind='EQUITY'AND control_kind IS NULL)THEN RAISE EXCEPTION 'Active non-control equity account required' USING ERRCODE='HR422';END IF;
 SELECT*INTO m FROM accounting.account_mappings WHERE company_id=c AND purpose='RETAINED_EARNINGS'FOR UPDATE;IF coalesce(m.version,0)IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'Retained earnings configuration changed' USING ERRCODE='HR409';END IF;
 INSERT INTO accounting.account_mappings(company_id,purpose,account_id)VALUES(c,'RETAINED_EARNINGS',p_account)ON CONFLICT(company_id,purpose)DO UPDATE SET account_id=EXCLUDED.account_id RETURNING version INTO v;RETURN v;END $$;

CREATE FUNCTION accounting.validate_year_entry()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
 DECLARE c uuid:=NEW.company_id;doc uuid;cl accounting.year_end_closings;rv accounting.year_end_reversals;fy accounting.fiscal_years;j uuid;reverse_entry boolean:=false;lines jsonb;profit numeric;BEGIN
 IF TG_TABLE_NAME IN('year_end_closings','year_end_reversals')THEN doc:=NEW.id;
 ELSIF TG_TABLE_NAME='posting_batches'THEN doc:=(to_jsonb(NEW)->>'source_document_id')::uuid;
 ELSE SELECT b.source_document_id INTO doc FROM accounting.journal_entries e JOIN accounting.posting_batches b ON b.company_id=e.company_id AND b.id=e.posting_batch_id WHERE e.company_id=c AND e.id=(to_jsonb(NEW)->>'journal_entry_id')::uuid;END IF;
 SELECT*INTO cl FROM accounting.year_end_closings WHERE company_id=c AND id=doc;
 IF NOT FOUND THEN SELECT*INTO rv FROM accounting.year_end_reversals WHERE company_id=c AND id=doc;IF NOT FOUND THEN RETURN NULL;END IF;SELECT*INTO cl FROM accounting.year_end_closings WHERE company_id=c AND id=rv.closing_id;reverse_entry:=true;END IF;
 SELECT*INTO fy FROM accounting.fiscal_years WHERE company_id=c AND id=cl.fiscal_year_id;j:=CASE WHEN reverse_entry THEN rv.journal_entry_id ELSE cl.journal_entry_id END;profit:=cl.profit;
 IF NOT EXISTS(SELECT 1 FROM platform.documents WHERE company_id=c AND id=doc AND state='POSTED'AND version=1 AND business_date=fy.ends_on-1 AND document_type=CASE WHEN reverse_entry THEN'YEAR_END_REVERSAL'ELSE'YEAR_END_CLOSING'END)THEN RAISE EXCEPTION 'Invalid registered annual closing document' USING ERRCODE='23514';END IF;
 IF NOT reverse_entry AND TG_TABLE_NAME='year_end_closings'AND cl.balances IS DISTINCT FROM(accounting.year_close_plan(cl.fiscal_year_id)->'balances')THEN RAISE EXCEPTION 'Annual closing does not match business nominal accounts' USING ERRCODE='23514';END IF;
 IF profit<>coalesce((SELECT -sum((x->>'balance')::numeric)FROM jsonb_array_elements(cl.balances)x),0)OR NOT EXISTS(SELECT 1 FROM accounting.accounts WHERE company_id=c AND id=cl.retained_account_id AND kind='EQUITY'AND control_kind IS NULL)OR EXISTS(SELECT 1 FROM jsonb_array_elements(cl.balances)x LEFT JOIN accounting.accounts a ON a.company_id=c AND a.id=(x->>'accountId')::uuid WHERE a.id IS NULL OR a.kind NOT IN('REVENUE','EXPENSE')OR a.control_kind IS NOT NULL OR a.kind IS DISTINCT FROM x->>'kind')THEN RAISE EXCEPTION 'Invalid annual closing account plan' USING ERRCODE='23514';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('accountId',x->>'accountId','debit',greatest(-(x->>'balance')::numeric,0),'credit',greatest((x->>'balance')::numeric,0))),'[]'::jsonb)INTO lines FROM jsonb_array_elements(cl.balances)x;
 IF profit<>0 THEN lines:=lines||jsonb_build_array(jsonb_build_object('accountId',cl.retained_account_id,'debit',greatest(-profit,0),'credit',greatest(profit,0)));END IF;
 IF j IS NULL THEN IF jsonb_array_length(lines)<>0 OR EXISTS(SELECT 1 FROM accounting.posting_batches WHERE company_id=c AND source_document_id=doc)THEN RAISE EXCEPTION 'Empty annual close must not post a journal' USING ERRCODE='23514';END IF;RETURN NULL;END IF;
 IF(SELECT count(*)FROM accounting.posting_batches WHERE company_id=c AND source_document_id=doc)<>1 OR NOT EXISTS(SELECT 1 FROM accounting.journal_entries e JOIN accounting.posting_batches b ON b.company_id=e.company_id AND b.id=e.posting_batch_id WHERE e.company_id=c AND e.id=j AND e.posting_date=fy.ends_on-1 AND b.source_document_id=doc AND b.source_version=1 AND b.posting_kind=CASE WHEN reverse_entry THEN'YEAR_END_REVERSAL'ELSE'YEAR_END_CLOSING'END)OR EXISTS(SELECT 1 FROM accounting.journal_lines WHERE company_id=c AND journal_entry_id=j AND(party_id IS NOT NULL OR source_line_id IS NOT NULL))THEN RAISE EXCEPTION 'Invalid annual posting registry or source' USING ERRCODE='23514';END IF;
 IF EXISTS(WITH expected AS(SELECT(x->>'accountId')::uuid AS account_id,sum((x->>CASE WHEN reverse_entry THEN'credit'ELSE'debit'END)::numeric)AS debit,sum((x->>CASE WHEN reverse_entry THEN'debit'ELSE'credit'END)::numeric)AS credit FROM jsonb_array_elements(lines)x GROUP BY(x->>'accountId')::uuid),actual AS(SELECT account_id,sum(debit)AS debit,sum(credit)AS credit FROM accounting.journal_lines WHERE company_id=c AND journal_entry_id=j GROUP BY account_id)SELECT 1 FROM expected e FULL JOIN actual a ON a.account_id=e.account_id WHERE coalesce(e.debit,0)<>coalesce(a.debit,0)OR coalesce(e.credit,0)<>coalesce(a.credit,0))THEN RAISE EXCEPTION 'Annual closing journal differs from immutable plan' USING ERRCODE='23514';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER year_entry_proof AFTER INSERT ON accounting.year_end_closings DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION accounting.validate_year_entry();
CREATE CONSTRAINT TRIGGER year_entry_proof AFTER INSERT ON accounting.year_end_reversals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION accounting.validate_year_entry();
CREATE CONSTRAINT TRIGGER year_entry_proof AFTER INSERT ON accounting.posting_batches DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION accounting.validate_year_entry();
CREATE CONSTRAINT TRIGGER year_entry_proof AFTER INSERT ON accounting.journal_lines DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION accounting.validate_year_entry();
CREATE FUNCTION accounting.guard_year_document()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN IF EXISTS(SELECT 1 FROM accounting.year_end_closings WHERE company_id=OLD.company_id AND id=OLD.id)OR EXISTS(SELECT 1 FROM accounting.year_end_reversals WHERE company_id=OLD.company_id AND id=OLD.id)THEN RAISE EXCEPTION 'Registered annual closing documents are immutable' USING ERRCODE='23514';END IF;RETURN coalesce(NEW,OLD);END $$;
CREATE TRIGGER year_document_immutable BEFORE UPDATE OR DELETE ON platform.documents FOR EACH ROW EXECUTE FUNCTION accounting.guard_year_document();
CREATE FUNCTION accounting.validate_year_control()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE n bigint;v uuid;BEGIN
 SELECT count(*),min(c.id::text)::uuid INTO n,v FROM accounting.year_end_closings c WHERE c.company_id=NEW.company_id AND c.fiscal_year_id=NEW.id AND NOT EXISTS(SELECT 1 FROM accounting.year_end_reversals r WHERE r.company_id=c.company_id AND r.closing_id=c.id);
 IF n>1 OR(NEW.state='CLOSED'AND(n<>1 OR NEW.current_closing_id IS DISTINCT FROM v))OR(NEW.state='OPEN'AND n<>0)THEN RAISE EXCEPTION 'Fiscal year status does not match active closing evidence' USING ERRCODE='23514';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER year_control_proof AFTER INSERT OR UPDATE ON accounting.fiscal_year_controls DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION accounting.validate_year_control();
CREATE OR REPLACE FUNCTION accounting.validate_journal() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE j_id uuid; c_id uuid; n int; d numeric; c numeric;
BEGIN
 IF TG_TABLE_NAME='journal_entries' THEN j_id:=NEW.id; ELSE j_id:=NEW.journal_entry_id; END IF;
 c_id:=NEW.company_id;
 SELECT count(*),COALESCE(sum(debit),0),COALESCE(sum(credit),0) INTO n,d,c
 FROM accounting.journal_lines WHERE company_id=c_id AND journal_entry_id=j_id;
 IF n<2 OR d<>c THEN RAISE EXCEPTION 'Journal must have at least two lines and balance exactly' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM accounting.journal_entries j JOIN accounting.periods p
 ON p.company_id=j.company_id AND j.posting_date>=p.starts_on AND j.posting_date<p.ends_on AND p.state='OPEN'
 WHERE j.company_id=c_id AND j.id=j_id) THEN
  IF EXISTS(SELECT 1 FROM accounting.year_end_journal_ids WHERE company_id=c_id AND journal_entry_id=j_id)THEN RETURN NULL;END IF;
  RAISE EXCEPTION 'Posting date is outside an open accounting period' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $$;

CREATE FUNCTION accounting.check_closed_periods()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET jit=off AS $$DECLARE c uuid;rec record;token text;cache text;BEGIN
 c:=CASE WHEN TG_TABLE_SCHEMA='core'AND TG_TABLE_NAME='companies'THEN coalesce(NEW.id,OLD.id)ELSE coalesce((to_jsonb(NEW)->>'company_id')::uuid,(to_jsonb(OLD)->>'company_id')::uuid)END;
 IF NOT EXISTS(SELECT 1 FROM accounting.periods WHERE company_id=c AND state='CLOSED'AND current_close_snapshot_id IS NOT NULL)THEN RETURN NULL;END IF;
 IF c IS DISTINCT FROM core.current_company()THEN RAISE EXCEPTION 'Accounting close company context mismatch' USING ERRCODE='HR409';END IF;
 token:=coalesce(current_setting('htt.bas_dirty',true),'');cache:='htt.period_checked_'||replace(c::text,'-','');IF current_setting(cache,true)=token THEN RETURN NULL;END IF;
 FOR rec IN SELECT p.starts_on,p.ends_on,s.financial_hash FROM accounting.periods p JOIN accounting.period_close_snapshots s ON s.company_id=p.company_id AND s.id=p.current_close_snapshot_id WHERE p.company_id=c AND p.state='CLOSED'LOOP
 IF accounting.close_hash(accounting.close_financials(rec.starts_on,rec.ends_on))<>rec.financial_hash THEN RAISE EXCEPTION 'Reopen the affected accounting periods before changing closed financial balances' USING ERRCODE='HR409';END IF;END LOOP;
 PERFORM set_config(cache,token,true);RETURN NULL;END $$;
DO $$BEGIN IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='core.companies'::regclass AND tgname='bas_lock')THEN EXECUTE 'CREATE TRIGGER bas_dirty BEFORE INSERT OR UPDATE OR DELETE ON core.companies FOR EACH STATEMENT EXECUTE FUNCTION accounting.bas_dirty()';EXECUTE 'CREATE TRIGGER bas_lock BEFORE INSERT OR UPDATE OR DELETE ON core.companies FOR EACH ROW EXECUTE FUNCTION accounting.bas_write_lock()';END IF;END $$;
