CREATE FUNCTION accounting.guard_fiscal_geometry()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN IF ROW(NEW.starts_on,NEW.ends_on,NEW.company_id)IS DISTINCT FROM ROW(OLD.starts_on,OLD.ends_on,OLD.company_id)AND(EXISTS(SELECT 1 FROM accounting.periods WHERE company_id=OLD.company_id AND fiscal_year_id=OLD.id AND current_close_snapshot_id IS NOT NULL)OR EXISTS(SELECT 1 FROM accounting.year_end_closings WHERE company_id=OLD.company_id AND fiscal_year_id=OLD.id))THEN RAISE EXCEPTION 'Managed fiscal-year dates are immutable' USING ERRCODE='HR409';END IF;RETURN NEW;END $$;
CREATE TRIGGER managed_year BEFORE UPDATE ON accounting.fiscal_years FOR EACH ROW EXECUTE FUNCTION accounting.guard_fiscal_geometry();
ALTER FUNCTION accounting.bas_transition(uuid,bigint,text,text,text,date)RENAME TO bas_transition_038;
REVOKE ALL ON FUNCTION accounting.bas_transition_038(uuid,bigint,text,text,text,date)FROM htt_app,PUBLIC;
CREATE FUNCTION accounting.bas_transition(p_id uuid,p_version bigint,p_action text,p_reference text,p_reason text,p_lodged date)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE c uuid:=core.current_company();b accounting.bas_periods;BEGIN
 IF p_action='REOPENED'THEN PERFORM accounting.bas_require_access('accounting.bas.reopen');PERFORM accounting.bas_lock(c,true);SELECT*INTO b FROM accounting.bas_effective_periods WHERE company_id=c AND id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'BAS period unavailable' USING ERRCODE='HT404';END IF;IF EXISTS(SELECT 1 FROM accounting.periods WHERE company_id=c AND state='CLOSED'AND starts_on<b.to_date AND ends_on>b.from_date)THEN RAISE EXCEPTION 'Reopen overlapping accounting periods before reopening BAS' USING ERRCODE='HR409';END IF;END IF;
 RETURN accounting.bas_transition_038(p_id,p_version,p_action,p_reference,p_reason,p_lodged);END $$;
ALTER FUNCTION accounting.create_bas_period_full(text,date,date,text,text,text,boolean,date,text)RENAME TO create_bas_period_full_038;
REVOKE ALL ON FUNCTION accounting.create_bas_period_full_038(text,date,date,text,text,text,boolean,date,text)FROM htt_app,PUBLIC;
CREATE FUNCTION accounting.create_bas_period_full(p_reference text,p_from date,p_to date,p_cadence text,p_basis text,p_method text,p_registered boolean,p_due date,p_calculation text)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE c uuid:=core.current_company();BEGIN
 PERFORM accounting.bas_require_access('accounting.bas.manage');PERFORM accounting.bas_lock(c,true);IF EXISTS(SELECT 1 FROM accounting.periods WHERE company_id=c AND state='CLOSED'AND starts_on<p_to AND ends_on>p_from)THEN RAISE EXCEPTION 'Reopen accounting periods before adding a BAS calendar over them' USING ERRCODE='HR409';END IF;
 RETURN accounting.create_bas_period_full_038(p_reference,p_from,p_to,p_cadence,p_basis,p_method,p_registered,p_due,p_calculation);END $$;
CREATE OR REPLACE FUNCTION accounting.create_bas_period(p_reference text,p_from date,p_to date,p_cadence text,p_basis text,p_method text,p_registered boolean,p_due date)RETURNS uuid LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT accounting.create_bas_period_full(p_reference,p_from,p_to,p_cadence,p_basis,p_method,p_registered,p_due,'ACCOUNTS')$$;
REVOKE ALL ON FUNCTION accounting.seed_year_control(),identity.seed_period_close_roles(uuid),accounting.require_close_access(text),accounting.write_year_journal(uuid,uuid,date,text,jsonb),accounting.check_closed_periods(),accounting.validate_year_entry(),accounting.validate_year_control(),accounting.guard_year_document(),accounting.close_period(uuid,bigint,text,text,boolean),accounting.reopen_period(uuid,bigint,text,text),accounting.close_fiscal_year(uuid,bigint,text,text),accounting.reopen_fiscal_year(uuid,bigint,text,text),accounting.configure_retained(uuid,bigint),accounting.create_fiscal_year(text,date,date)FROM PUBLIC;
GRANT SELECT ON accounting.fiscal_year_controls,accounting.period_close_snapshots,accounting.period_close_events,accounting.year_end_closings,accounting.year_end_reversals,accounting.year_end_journal_ids,accounting.business_journal_entries,accounting.close_stock_movements TO htt_app;
GRANT EXECUTE ON FUNCTION accounting.period_preflight(uuid,boolean),accounting.close_financials(date,date),accounting.close_hash(jsonb),accounting.year_closing_bridge(date),accounting.year_close_plan(uuid),accounting.close_period(uuid,bigint,text,text,boolean),accounting.reopen_period(uuid,bigint,text,text),accounting.close_fiscal_year(uuid,bigint,text,text),accounting.reopen_fiscal_year(uuid,bigint,text,text),accounting.configure_retained(uuid,bigint),accounting.create_fiscal_year(text,date,date),accounting.bas_transition(uuid,bigint,text,text,text,date),accounting.create_bas_period_full(text,date,date,text,text,text,boolean,date,text)TO htt_app;

REVOKE ALL ON FUNCTION accounting.close_financials(date,date),accounting.close_hash(jsonb),accounting.year_closing_bridge(date) FROM PUBLIC,htt_app;
REVOKE ALL ON FUNCTION accounting.period_preflight(uuid,boolean),accounting.year_close_plan(uuid),accounting.guard_period_state(),accounting.lock_calendar(),accounting.guard_fiscal_geometry() FROM PUBLIC;

ALTER TABLE accounting.year_end_closings ADD CHECK(length(btrim(reference))BETWEEN 1 AND 200 AND length(btrim(reason))BETWEEN 1 AND 2000 AND jsonb_typeof(balances)='array'AND profit=round(profit,2)AND abs(profit)<=999999999999999999.99);
ALTER TABLE accounting.year_end_reversals ADD CHECK(length(btrim(reference))BETWEEN 1 AND 200 AND length(btrim(reason))BETWEEN 1 AND 2000);
CREATE INDEX period_closed_snapshot ON accounting.periods(company_id,ends_on)WHERE state='CLOSED'AND current_close_snapshot_id IS NOT NULL;

REVOKE ALL ON FUNCTION accounting.bas_transition(uuid,bigint,text,text,text,date),accounting.create_bas_period_full(text,date,date,text,text,text,boolean,date,text) FROM PUBLIC;

DO $$DECLARE c uuid;BEGIN FOR c IN SELECT id FROM core.companies LOOP
 PERFORM set_config('htt.company_id',c::text,true);PERFORM identity.seed_period_close_roles(c);
 INSERT INTO accounting.fiscal_year_controls(id,company_id)SELECT id,company_id FROM accounting.fiscal_years WHERE company_id=c;
 SET CONSTRAINTS ALL IMMEDIATE;SET CONSTRAINTS ALL DEFERRED;
 END LOOP;PERFORM set_config('htt.company_id','',true);END $$;
